L["%s, level %d, saved %s%s. Click to put its link in the box above, shift-click to put it in chat. Try it rings its talents on your trees."] = "%s, niveau %d, enregistré le %s%s. Cliquez pour mettre son lien dans la zone ci-dessus, Maj-clic pour le mettre dans la discussion. Essayer entoure ses talents sur vos arbres."
L[" on %s"] = " sur %s"
L["Ask for their builds"] = "Demander leurs builds"
L["Asked your group. Each build lands here as it arrives."] = "Demande envoyée à votre groupe. Chaque build s'affiche ici dès son arrivée."
L["Your group's builds"] = "Les builds de votre groupe"
L["Everyone in your group who runs the addon answers with their plan. Nothing is posted in chat."] = "Chaque membre de votre groupe qui a l'addon répond avec son plan. Rien n'est publié dans la discussion."
L["Nothing yet. Press the button; anyone in your group with the addon answers."] = "Rien pour l'instant. Appuyez sur le bouton ; les membres du groupe qui ont l'addon répondent."
L["%s's %s build"] = "%s : build %s"
L["Level %d, %s. Try it rings its talents on your trees next to yours, Load makes it your plan, shift-click puts its link in chat."] = "Niveau %d, %s. Essayer entoure ses talents sur vos arbres à côté des vôtres, Charger en fait votre plan, Maj-clic met son lien dans la discussion."
L["No numbers for this class yet."] = "Pas encore de chiffres pour cette classe."
L["%s builds on talentsforever.com"] = "Builds %s sur talentsforever.com"
L["most built"] = "le plus courant"
L["%sShared %d, saved %d, opened %d times%s. Try it rings its talents on your trees next to yours, Load makes it your plan."] = "%sPartagé %d fois, enregistré %d fois, ouvert %d fois%s. Essayer entoure ses talents sur vos arbres à côté des vôtres, Charger en fait votre plan."
L["The most built %s build, #%d overall. "] = "Le build %s le plus courant, n°%d au classement général. "
L[", across %d close builds (every full build within four points of this one)"] = ", sur %d builds proches (tout build complet à quatre points ou moins de celui-ci)"
L["Almost everyone takes"] = "Presque tous prennent"
L["Almost nobody takes"] = "Presque personne ne prend"
L["Show pick rates"] = "Afficher la popularité"
L["A gold edge is a talent new in Forever, blue changed its numbers or words, purple moved trees or rows. Hover a tile for the Classic text."] = "Bord doré : talent nouveau dans Forever. Bleu : chiffres ou texte modifiés. Violet : talent qui a changé d'arbre ou de rangée. Survolez une case pour voir le texte de Classic."
L["The share of this class's builds on the site with at least one point in the talent."] = "La part des builds de cette classe sur le site qui ont au moins un point dans le talent."
L["%s against Classic: |cffffd75e%d new|r, |cff58a6ff%d changed|r, |cffb88cff%d moved|r, %d the same."] = "%s face à Classic : |cffffd75enouveaux : %d|r, |cff58a6ffmodifiés : %d|r, |cffb88cffdéplacés : %d|r, identiques : %d."
L["|cffffd75eNew:|r "] = "|cffffd75eNouveaux :|r "
L["|cffff4d4dGone from Classic:|r "] = "|cffff4d4dRetirés depuis Classic :|r "
L["Cannot be a %s. Click for its racials anyway."] = "Ne peut pas être %s. Cliquez quand même pour voir ses traits raciaux."
L["Your race. Click another face for its racials with this class."] = "Votre race. Cliquez sur un autre visage pour voir ses traits raciaux avec cette classe."
L["Click for its racials with this class."] = "Cliquez pour voir ses traits raciaux avec cette classe."
L["YOUR RACE"] = "VOTRE RACE"
L["NOT A %s RACE"] = "PAS UNE RACE DE %s"
L["YOU ARE %s"] = "VOUS ÊTES %s"
L["%s %s ONLY"] = "%s, %s UNIQUEMENT"
L["No racial notes for this race on the site yet."] = "Pas encore de notes raciales pour cette race sur le site."
L["Skip"] = "Ignorer"
L["Scales with %s."] = "Évolue avec %s."
L["The trainer sells this from level %d%s.%s"] = "Le maître l'enseigne dès le niveau %d%s.%s"
L[" for %s"] = " pour %s"
L[" A portal trainer, not the class trainer."] = " Un maître des portails, pas le maître de classe."
L["Skipped: it stays out of the reminders. Back, or a right click, puts it back."] = "Ignoré : ce sort n'apparaît plus dans les rappels. Retour, ou un clic droit, le rétablit."
L["Skip, or a right click, keeps it out of the reminders for this character."] = "Ignorer, ou un clic droit, le retire des rappels pour ce personnage."
L["Spellbook up to date"] = "Grimoire à jour"
L["It has everything the trainer sells at your level."] = "Il contient tout ce que le maître enseigne à votre niveau."
L["AT THE TRAINER, %d YOU CAN LEARN NOW"] = "CHEZ LE MAÎTRE, %d À APPRENDRE MAINTENANT"
L["%s to learn them."] = "%s pour tout apprendre."
L["Settings"] = "Options"
L["Level-up reminders"] = "Rappels de niveau"
L["When you level up, a small card says which talent is next and offers to place it."] = "Quand vous montez de niveau, une petite carte indique le talent suivant et propose de le placer."
L["Trainer reminders"] = "Rappels du maître"
L["A card when you level, or walk into a city, with spells you could learn. Once per level, per place. Off by itself if What's Training is installed."] = "Une carte quand vous montez de niveau ou entrez dans une ville, avec les sorts que vous pourriez apprendre. Une fois par niveau et par lieu. Se désactive d'elle-même si What's Training est installé."
L["Trainer cards only for what you can afford"] = "Cartes du maître : sorts abordables seulement"
L["The card counts only the spells your gold covers, with one line for the rest, and stays away while none is affordable; it comes when the gold does. The card itself offers this the first time it lists something you cannot pay for. Prices come from the trainer window once you have opened one on this character."] = "La carte ne compte que les sorts que votre or peut payer, avec une ligne pour le reste, et reste cachée tant qu'aucun n'est abordable ; elle arrive avec l'or. La carte elle-même le propose la première fois qu'elle affiche quelque chose que vous ne pouvez pas payer. Les prix viennent de la fenêtre du maître dès que vous en avez ouvert une avec ce personnage."
L["Game-style class list"] = "Liste des classes du jeu"
L["The class picker changes on the next /reload."] = "Le sélecteur de classe change au prochain /reload."
L["The class picker at the top is the game's own dropdown. Off uses a plain button instead. It switches itself off if the game ever blocks the dropdown, and while a gamepad is on."] = "Le sélecteur de classe en haut est le menu déroulant du jeu. Désactivé, c'est un simple bouton. Il se désactive de lui-même si le jeu bloque le menu déroulant, et tant qu'une manette est active."
L["Show other people's builds"] = "Afficher les builds des autres"
L["Off hides the Popular page and the cards other players send. Links in chat still work."] = "Désactivé, masque la page Populaires et les cartes envoyées par les autres joueurs. Les liens dans la discussion fonctionnent toujours."
L["Answer build requests"] = "Répondre aux demandes de build"
L["Someone in your group can ask everyone for their build. On, yours goes to them as a link. Off, nothing goes."] = "Un membre de votre groupe peut demander son build à chacun. Activé, le vôtre lui est envoyé sous forme de lien. Désactivé, rien n'est envoyé."
L["The #1 build for your class becomes your plan. Each level, a card asks before the next point goes in. Change a point by hand and it stops."] = "Le build n°1 de votre classe devient votre plan. À chaque niveau, une carte vous demande avant de placer le point suivant. Modifiez un point à la main et le suivi s'arrête."
L["Place points for me, no asking"] = "Placer les points sans demander"
L["Each time you level, the plan's next point is placed without a card. Never your first point in a tree: that one always asks. Off unless you want it."] = "À chaque niveau, le point suivant du plan est placé sans carte. Jamais votre premier point dans un arbre : celui-là demande toujours. Désactivé, sauf si vous le voulez."
L["Show plan on the game's talents"] = "Afficher le plan sur les talents du jeu"
L["Your plan's numbers and a ring on your next point, drawn on the game's own talent window."] = "Les chiffres de votre plan et un cercle sur votre point suivant, affichés dans la fenêtre des talents du jeu."
L["Leveling rail"] = "Frise des niveaux"
L["The bar under the trees, one mark per level. Off, the window is shorter. At 60 it is off by itself."] = "La barre sous les arbres, un repère par niveau. Désactivée, la fenêtre est moins haute. Au niveau 60, elle se désactive d'elle-même."
L["Sounds"] = "Sons"
L["Small clicks and chimes."] = "Petits clics et carillons."
L["Minimap button"] = "Bouton de la minicarte"
L["The book on the minimap. Left click opens the planner, right click the popular builds."] = "Le livre sur la minicarte. Clic gauche ouvre le planificateur, clic droit les builds populaires."
L["Book tab on the character pane"] = "Onglet livre sur la fiche de personnage"
L["The book among the tabs on your character pane. Same as /tf."] = "Le livre parmi les onglets de votre fiche de personnage. Comme /tf."
L["Train all at the trainer"] = "Tout apprendre chez le maître"
L["The Train all button on the trainer window, with what it would cost. Off, the trainer window is the game's own; /talents trainall still buys the lot."] = "Le bouton Tout apprendre dans la fenêtre du maître, avec son coût. Désactivé, la fenêtre du maître reste celle du jeu ; /talents trainall achète toujours tout."
L["The talents key opens this"] = "La touche des talents ouvre ceci"
L["Whatever key opens the game's talents (N, unless you changed it) opens Talents Forever instead. Your key bindings stay as they are; off gives the game's window back."] = "La touche qui ouvre les talents du jeu (N, sauf si vous l'avez changée) ouvre Talents Forever à la place. Vos raccourcis restent tels quels ; désactivé, la fenêtre du jeu revient."
L["Talent and spell names in English"] = "Noms des talents et sorts en anglais"
L["The names come from the game in its own language. On, they read in English instead, the way guides and the site write them. The addon's own words stay in your language."] = "Les noms viennent du jeu, dans sa langue. Activé, ils s'affichent en anglais, comme dans les guides et sur le site. Les textes de l'addon restent dans votre langue."
L["Open this instead of the game's talents"] = "Ouvrir ceci à la place des talents du jeu"
L["The game's talent tab opens Talents Forever now. Hold Shift while opening it for the game's window."] = "L'onglet des talents du jeu ouvre désormais Talents Forever. Maintenez Maj en l'ouvrant pour avoir la fenêtre du jeu."
L["The game's talent window is its own again."] = "La fenêtre des talents du jeu est de retour."
L["Open the game's talents any way at all (the key, the micro bar, the spellbook's tab) and it closes again with Talents Forever in its place. Hold Shift while opening it to get the game's window that once. Never during a fight."] = "Ouvrez les talents du jeu par n'importe quel moyen (la touche, le micro-menu, l'onglet du grimoire) : ils se referment et Talents Forever s'ouvre à leur place. Maintenez Maj en les ouvrant pour avoir la fenêtre du jeu cette fois-là. Jamais en combat."
L["Window size"] = "Taille de la fenêtre"
L["Drag the knob, or click anywhere on the bar. One percent at a time. Ctrl and the wheel on the window do the same."] = "Faites glisser le curseur ou cliquez n'importe où sur la barre. Un pour cent à la fois. Ctrl et la molette sur la fenêtre font de même."
L["Center the window"] = "Centrer la fenêtre"
L["Window centered."] = "Fenêtre centrée."
L["Reminder card back to the middle"] = "Recentrer les cartes de rappel"
L["The cards show above the bottom of the screen again. Drag one to put them somewhere else."] = "Les cartes s'affichent de nouveau en bas de l'écran. Faites-en glisser une pour les placer ailleurs."
L["Where the cards show"] = "Emplacement des cartes"
L["The level-up, trainer and build cards can be dragged anywhere on the screen; they stay where you drop them. This puts them back above the bottom, in the middle."] = "Les cartes de niveau, du maître et de build se déplacent n'importe où à l'écran ; elles restent là où vous les lâchez. Ceci les remet en bas, au centre."
L["Ctrl + wheel resizes, so do the bottom corners. Escape closes."] = "Ctrl + molette redimensionne, tout comme les coins inférieurs. Échap ferme."
L["Back to the middle"] = "Retour au centre"
L["Puts the window in the middle of the screen. Drag the title to move it, the corner to resize it."] = "Place la fenêtre au centre de l'écran. Faites glisser le titre pour la déplacer, le coin pour la redimensionner."
L["Never posts in chat on its own. A link goes out only when you send it."] = "Ne publie jamais rien de lui-même dans la discussion. Un lien ne part que lorsque vous l'envoyez."
L["Also goes away when Show other people's builds is off."] = "Disparaît aussi quand Afficher les builds des autres est désactivé."
L["Feedback"] = "Retours"
L["Say what would help"] = "Dites ce qui vous aiderait"
L["A bug, a wish, a talent that reads wrong: it goes to the inbox of the person who builds this."] = "Un bug, un souhait, un talent mal décrit : tout arrive dans la boîte de réception de la personne qui crée cet addon."
L["Done"] = "Fait"
L["On the way"] = "En cours"
L["Thinking about it"] = "À l'étude"
L["Not this one"] = "Non retenu"
L["on Reddit"] = "sur Reddit"
L["on the site"] = "sur le site"
L["a %s, level %d, %s"] = "un %s, niveau %d, %s"
L["someone %s, %s"] = "quelqu'un %s, %s"
L["from inside the addon"] = "depuis l'addon"
L["A bug, a wish, a talent that reads wrong. It goes to the person who builds this."] = "Un bug, un souhait, un talent mal décrit. Tout arrive à la personne qui crée cet addon."
L["Say it how you would say it to a friend."] = "Dites-le comme vous le diriez à un ami."
L["460 left"] = "460 restants"
L["Select"] = "Sélectionner"
L["%d left"] = "%d restants"
L["Reddit name, if you want a reply"] = "Nom Reddit, si vous voulez une réponse"
L["Send"] = "Envoyer"
L["Ctrl+C"] = "Ctrl+C"
L["Link ready and selected: Ctrl+C, then paste it in a browser."] = "Lien prêt et sélectionné : Ctrl+C, puis collez-le dans un navigateur."
L["Makes a link out of the note and selects it. Ctrl+C, paste it in any browser, and it is delivered."] = "Transforme la note en lien et le sélectionne. Ctrl+C, collez-le dans un navigateur, et c'est envoyé."
L["Link selected. Now press Ctrl+C, then paste it in any browser."] = "Lien sélectionné. Appuyez sur Ctrl+C, puis collez-le dans un navigateur."
L["To send it: Select, then Ctrl+C, then paste the link in any browser. An addon cannot copy for you."] = "Pour l'envoyer : Sélectionner, puis Ctrl+C, puis collez le lien dans un navigateur. Un addon ne peut pas copier à votre place."
L["The page answers Got it. Nothing leaves the game by itself, and your character's name is not in it. The link carries a six-letter tag the addon made up, so a reply can show up here, under your note."] = "La page répond « Got it ». Rien ne quitte le jeu tout seul, et le nom de votre personnage n'y figure pas. Le lien porte une étiquette de six lettres inventée par l'addon, pour qu'une réponse puisse s'afficher ici, sous votre note."
L["Every note that turned into something, in the words it came in."] = "Chaque note qui a abouti à quelque chose, dans ses propres mots."
L[" As of %s."] = " Au %s."
L[" And %d of you just said thanks. Noted."] = " Et %d d'entre vous ont simplement dit merci. C'est noté."
L["Your note. %s"] = "Votre note. %s"
