L["Each class keeps its own plan on this character. Apply only ever touches your own."] = "Chaque classe garde son propre plan sur ce personnage. Appliquer ne touche jamais qu'à votre propre classe."
L["%s plan open. Your %s plan is kept."] = "Plan %s ouvert. Votre plan %s est conservé."
L["Plan another class"] = "Planifier une autre classe"
L["Class"] = "Classe"
L["Opens the classes right here. "] = "Ouvre les classes ici même. "
